import os
from datetime import datetime, timezone, timedelta
from typing import Any, Dict, List, Optional

import boto3
from botocore.config import Config


def _to_epoch_ms(value: Any) -> int:
    if isinstance(value, (int, float)):
        return int(value)
    if isinstance(value, datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return int(value.timestamp() * 1000)
    if isinstance(value, str):
        s = value.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return int(dt.timestamp() * 1000)
    raise TypeError("time values must be datetime, ISO-8601 string, int, or float")


def query_recent_error_logs(
    log_group_name: str,
    severity: str = "ERROR",
    start_time: Optional[Any] = None,
    end_time: Optional[Any] = None,
    limit: int = 100,
    region_name: Optional[str] = None,
    log_stream_names: Optional[List[str]] = None,
) -> List[Dict[str, Any]]:
    client = boto3.client(
        "logs",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
        config=Config(retries={"max_attempts": 10, "mode": "standard"}),
    )

    if end_time is None:
        end_ms = int(datetime.now(timezone.utc).timestamp() * 1000)
    else:
        end_ms = _to_epoch_ms(end_time)

    if start_time is None:
        start_ms = int((datetime.now(timezone.utc) - timedelta(hours=1)).timestamp() * 1000)
    else:
        start_ms = _to_epoch_ms(start_time)

    if start_ms > end_ms:
        raise ValueError("start_time must be before or equal to end_time")

    severity = severity.upper().strip()
    filter_pattern = f'"{severity}"'

    params: Dict[str, Any] = {
        "logGroupName": log_group_name,
        "startTime": start_ms,
        "endTime": end_ms,
        "filterPattern": filter_pattern,
        "limit": limit,
    }
    if log_stream_names:
        params["logStreamNames"] = log_stream_names

    results: List[Dict[str, Any]] = []
    paginator = client.get_paginator("filter_log_events")

    for page in paginator.paginate(**params):
        for event in page.get("events", []):
            results.append(
                {
                    "event_id": event.get("eventId"),
                    "timestamp": event.get("timestamp"),
                    "ingestion_time": event.get("ingestionTime"),
                    "log_stream_name": event.get("logStreamName"),
                    "message": event.get("message"),
                }
            )
            if len(results) >= limit:
                return results

    return results
